contract InvMutTest {
    C c;

    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    function run(uint value, address target) public payable {
        require(target != address(0), "target must be nonzero");
        require(msg.sender != address(this), "caller must not be owner");

        uint balBefore = address(c).balance;
        uint countBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted1;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted1 = true; } else { reverted1 = false; }

        uint balAfter1 = address(c).balance;
        uint countAfter1 = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted2;
        c.withdraw(value); bool __rev1 = __ESBMC_reverted(); if (__rev1) { reverted2 = true; } else { reverted2 = false; }

        uint balAfter2 = address(c).balance;
        uint countAfter2 = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted3;
        c.sendMoney(target, value); bool __rev2 = __ESBMC_reverted(); if (__rev2) { reverted3 = true; } else { reverted3 = false; }

        uint balAfter3 = address(c).balance;
        uint countAfter3 = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert((reverted1 || (balAfter1 <= balBefore && countAfter1 == countBefore)) &&
               (reverted2 || (balAfter2 <= balAfter1 && countAfter2 == countAfter1)) &&
               (reverted3 || (balAfter3 <= balAfter2 && countAfter3 == countAfter2)));
    }

    receive() external payable {}
