pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {SimpleWallet} from "../src/SimpleWallet.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    SimpleWallet c;

    function setUp() public {
        c = new SimpleWallet();
    }

    function _run(uint256 value, address target) internal {
        vm.assume(target != address(0));
        vm.assume(msg.sender != address(this));
        uint balBefore = address(c).balance;
        uint256 countBefore;
        try c.depositsCount() returns (uint256 __r) { countBefore = __r; } catch { return; }
        bool reverted1;
        try c.withdrawAll() { reverted1 = false; } catch { reverted1 = true; }
        uint balAfter1 = address(c).balance;
        uint256 countAfter1;
        try c.depositsCount() returns (uint256 __r) { countAfter1 = __r; } catch { return; }
        bool reverted2;
        try c.withdraw(value) { reverted2 = false; } catch { reverted2 = true; }
        uint balAfter2 = address(c).balance;
        uint256 countAfter2;
        try c.depositsCount() returns (uint256 __r) { countAfter2 = __r; } catch { return; }
        bool reverted3;
        try c.sendMoney(target, value) { reverted3 = false; } catch { reverted3 = true; }
        uint balAfter3 = address(c).balance;
        uint256 countAfter3;
        try c.depositsCount() returns (uint256 __r) { countAfter3 = __r; } catch { return; }
        assertTrue((reverted1 || (balAfter1 <= balBefore && countAfter1 == countBefore)) &&
               (reverted2 || (balAfter2 <= balAfter1 && countAfter2 == countAfter1)) &&
               (reverted3 || (balAfter3 <= balAfter2 && countAfter3 == countAfter2)));
    }

    function testFuzz_run(uint256 value, address target) public {
        vm.assume(target.code.length == 0 && uint160(target) > 0xffff && target != address(this) && target != address(c) && target != 0x7109709ECfa91a80626fF3989D68f67F5b1DD12D && target != 0x000000000000000000636F6e736F6c652e6c6f67 && target != 0x4e59b44847b379578588920cA78FbF26c0B4956C && target != 0x1804c8AB1F12E6bbf3894d4083f33e07309d1f38);
        _run(value, target);
    }

    receive() external payable {}
}
